{"packet_id": "D043-02", "doc_id": "D043", "jurisdiction": "Los Angeles, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "LA RSO/JCO relocation assistance amounts 2026-27", "requirement": "Relocation assistance is paid per unit, not per tenant, at the Chart A RSO or JCO amounts, which increase every July 1st.", "key_value": "$11,000 to $27,400 per unit", "coverage_conditions": "Households above low income displaced for demolition for new construction, and tenants displaced under the RSO or JCO; amount depends on eligible or qualified status and tenancy length.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": "Amount depends on tenant status, tenancy length and income"}, "exemptions": "Single family dwellings that are not lower income may instead be entitled to one month's equivalent of rent depending on various factors.", "penalty": null, "effective_date": "2026-07-01", "citation": "LAMC § 165.06, relocation assistance amounts, Chart A, 2026-2027", "quoted_span": "CHART A: RSO or JCO Amounts Effective July 1, 2026 through June 30, 2027 (Increases July 1st) Household Type Less than 3 Years 3 or More Years or Low Income Eligible Tenant $11,000 $14,400 Qualified Tenant $23,150 $27,400", "interaction": null, "confidence": 0.75, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D043-02", "doc_id": "D043", "jurisdiction": "Los Angeles, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "LA RPO standardized relocation payments 2026-27", "requirement": "Lower income households displaced by new development under the Resident Protections Ordinance receive standardized relocation payments set by income tier, increasing every July 1st.", "key_value": "$115,480 / $96,750 / $87,450 per unit", "coverage_conditions": "Only low, very low and extremely low income households displaced by new development; households above low income are paid under Chart A RSO or JCO amounts.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": "Low, very low or extremely low income household displaced by new development"}, "exemptions": "Households above low income use Chart A RSO or JCO amounts instead of Chart B.", "penalty": null, "effective_date": "2026-07-01", "citation": "Los Angeles Resident Protections Ordinance #188481, Chart B standardized payments, 2026-2027", "quoted_span": "CHART B: Resident Protections Ordinance Standardized Payments (Only for Low, Very Low and Extremely Low Income Households) Effective July 1, 2026 through June 30, 2027 (Increases July 1st) Household Type Extremely Low Income Very Low Income Low Income Above Low Income Tenants Displaced by New Development $115,480 $96,750 $87,450", "interaction": null, "confidence": 0.75, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D043-02", "doc_id": "D043", "jurisdiction": "CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "California Housing Crisis Act relocation for lower income tenants displaced by new construction", "requirement": "Lower income households displaced by demolition where the owner will build new construction must receive relocation payment consistent with benefits public entities must pay under state law.", "key_value": null, "coverage_conditions": "Lower income households being displaced for demolition of their unit where the owner will replace the units with new construction.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": "Lower income household displaced by demolition for new construction"}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "Cal. Gov. Code § 66300.6", "quoted_span": "● Demolition for New Construction The City’s Resident Protections Ordinance (RPO) and the State’s Housing Crisis Act (HCA) require that ONLY lower income households being displaced for the purpose of demolition of their units where the owner will replace the units with new construction must receive relocation payment consistent  to the relocation benefits required to be paid by public entities pursuant to Chapter 16 (commencing with Section 7260) of Division 7 of Title 1 (Government Code 66300.6(b)(4)(A)).", "interaction": "Tenants displaced for new construction receive a minimum of the RSO or JCO amounts, increased only if the HCA or RPO requires it.", "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D043-02", "doc_id": "D043", "jurisdiction": "Los Angeles, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "LA JCO relocation for single-family dwelling owned by a natural person", "requirement": "Where a JCO single-family dwelling is owned by a natural person with no more than four dwelling units and one separate single-family home, relocation assistance is one month's rent in effect when the notice was served.", "key_value": "1 month's rent", "coverage_conditions": "Single-family dwellings subject to the JCO owned by a natural person, including through a trust or controlled legal entity, who owns no more than four dwelling units and a single-family home on a separate lot in the City of Los Angeles.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": 4, "owner_dependent": true, "other": "Single-family dwelling owned by a natural person"}, "exemptions": "Los Angeles Municipal Code Section 151.30(E) shall not apply.", "penalty": null, "effective_date": null, "citation": "LAMC § 165.06, single-family dwelling owned by natural person: one month's rent", "quoted_span": "a single-family dwelling subject to the JCO and the owner is a natural person, including natural persons who hold properties in a trust or registered legal entity controlled by that natural person, who owns no more than four dwelling units and a single-family home on a separate lot in the City of Los Angeles: one month’s rent that was in effect when the landlord served the written notice to terminate the tenancy", "interaction": null, "confidence": 0.75, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D043-02", "doc_id": "D043", "jurisdiction": "Los Angeles, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "LA relocation assistance payment timing", "requirement": "Relocation assistance must be made available within 15 days of service of the written notice of eviction, unless the landlord elects to pay the benefits through an escrow account.", "key_value": "15 days", "coverage_conditions": "Relocation assistance owed to tenants displaced under the city ordinances for demolition or no-fault eviction.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "LAMC § 165.06, relocation assistance payment timing", "quoted_span": "4. Payments shall be made available within fifteen (15) days of service of the written notice of eviction; however, the landlord may, at the landlord's sole discretion and at the landlord's cost, elect to pay the monetary relocation benefits through an escrow account. The monies must be placed in the escrow account within the required 15-day period.", "interaction": null, "confidence": 0.75, "conflict_flag": false, "conflict_note": null}
